insert into public.business_divisions (id, slug, name, short_name, tagline, description, kind, accent_color, hero_image, banner_image, logo_url, sort_order, is_active) values ('00000001-0000-4000-8000-000000000001', 'fashion', 'RAVANTRA Fashion', 'Fashion', 'Considered clothing for every chapter.', 'Dresses, ethnic heirlooms and modern wardrobe staples — cut in natural fabrics and finished by hand in our Jaipur and Mumbai ateliers.', 'products', '#211B20', '/images/fashion/tiger-crest-hoodie.webp', '/images/fashion/fashion-banner.webp', null, 1, true) on conflict (id) do nothing;
