insert into public.business_divisions (id, slug, name, short_name, tagline, description, kind, accent_color, hero_image, banner_image, logo_url, sort_order, is_active) values ('00000001-0000-4000-8000-000000000004', 'lifestyle', 'RAVANTRA Lifestyle', 'Lifestyle', 'The finishing touch, kept for years.', 'Leather handbags, fine-finish jewellery, fragrance and accessories — small objects with a long life, chosen to be worn and passed on.', 'products', '#B69A72', 'https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=1600&q=80', 'https://images.unsplash.com/photo-1599643478518-a784e5dc4c8f?auto=format&fit=crop&w=1600&q=80', null, 4, true) on conflict (id) do nothing;
