insert into public.products (id, division_id, category_id, slug, name, sku, short_description, description, price, sale_price, ingredients, highlights, tags, is_featured, is_new, is_active, created_at) values ('00000003-0000-4000-8000-000000000022', '00000001-0000-4000-8000-000000000001', '00000002-0000-4000-8000-000000000002', 'rouge-bandhani-predraped-saree', 'Rouge Bandhani Pre-draped Saree', 'RV-FA-034', 'A ready-to-wear bandhani drape with an embroidered bustier blouse.', 'Traditional red-and-ivory bandhani on featherlight georgette, pre-pleated and stitched so it drapes in under a minute. The sleeveless bustier blouse is embroidered with gold thread and sequins along a scalloped neckline — heritage craft, modern ease.', 12500, null, null, array['Hand-tied bandhani print','Pre-stitched pleats & pallu','Embroidered bustier blouse','Concealed side zip']::text[], array['saree','festive','ready-to-wear']::text[], true, true, true, now() - interval '7 days 0 hours') on conflict (id) do nothing;
