insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000001', '00000003-0000-4000-8000-000000000001', 'Ishita M.', 5, 'Feels like wearing water', 'The silk is beautiful and the wrap is genuinely flattering. I wore it to a friend''s engagement and was asked about it all evening.', true, now() - interval '12 days 0 hours') on conflict (id) do nothing;
insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000002', '00000003-0000-4000-8000-000000000001', 'Rhea K.', 4, 'Gorgeous print', 'Runs a touch long on me (5''2") but the print and fabric are lovely.', true, now() - interval '20 days 0 hours') on conflict (id) do nothing;
insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000003', '00000003-0000-4000-8000-000000000005', 'Priya S.', 5, 'An heirloom piece', 'The zari work is exquisite and it drapes so well. The gift box made it feel very special.', true, now() - interval '6 days 0 hours') on conflict (id) do nothing;
insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000004', '00000003-0000-4000-8000-000000000004', 'Neha V.', 5, 'Delicate, real chikankari', 'You can see the hand embroidery up close. Comfortable for a long day of Diwali visits.', true, now() - interval '9 days 0 hours') on conflict (id) do nothing;
insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000005', '00000003-0000-4000-8000-00000000000d', 'Aditi R.', 5, 'My skin has never looked better', 'Two weeks in and my skin is visibly brighter. Absorbs fast and doesn''t break me out.', true, now() - interval '15 days 0 hours') on conflict (id) do nothing;
