insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000007', '00000003-0000-4000-8000-000000000014', 'Kritika D.', 5, 'Frizz, gone', 'I use it as a pre-wash mask and a drop to finish. Hair feels softer and stronger.', true, now() - interval '18 days 0 hours') on conflict (id) do nothing;
