insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000009', '00000003-0000-4000-8000-000000000016', 'Tanvi P.', 5, 'Better than expected', 'The leather is rich and the structure holds beautifully. Fits a phone, wallet and a small pouch.', true, now() - interval '11 days 0 hours') on conflict (id) do nothing;
